#!/usr/bin/env python3
"""Bake a crawlable link to every released episode into episodes.html.

Why: the /episodes library paints its cards with JavaScript, so the raw HTML had no
<a href> to any episode and search engines could not follow the archive. This writes
one normal <a class="ecard" href="/{slug}"> per released episode (same markup the page
JavaScript uses) between the EP-LINKS markers inside #grid. The page JavaScript
shows / hides / re-orders these nodes and never deletes them.

  default : rewrite the baked block from data/catalogue.json (idempotent)
  --check : exit 1 if the baked block is missing or out of date (writes nothing)

Released = catalogue date on or before today in Australia/Sydney. The catalogue only
lists released or listed episodes, so staged episodes that are not in it never appear.
Only ever edits episodes.html. The new text is swapped in atomically. Standard library
only. Run by .github/workflows/scheduled-publish.yml after promote.py (never blocks a
release) and by scripts/merge_episode.py on the Mac.
"""
import datetime
import html
import json
import os
import re
import sys
import tempfile

try:
    from zoneinfo import ZoneInfo
    TODAY = datetime.datetime.now(ZoneInfo("Australia/Sydney")).date()
except Exception:  # pragma: no cover - fall back to UTC if tz data is missing
    TODAY = datetime.datetime.utcnow().date()

PAGE = "episodes.html"
START = "<!-- EP-LINKS:START (generated by .github/scripts/bake_episode_links.py from data/catalogue.json; do not edit by hand) -->"
END = "<!-- EP-LINKS:END -->"
SLUG_OK = re.compile(r"^[a-z0-9][a-z0-9-]*$")
BLOCK = re.compile(re.escape(START[:START.index(" (")]) + r".*?" + re.escape(END), re.S)
VISIBLE_AT_LOAD = 12  # same as PAGE in the page script; the rest start hidden until the script runs
MONTHS = ["", "January", "February", "March", "April", "May", "June", "July", "August",
          "September", "October", "November", "December"]


def esc(t):
    return html.escape(str(t), quote=True)


def fmt_date(iso):
    y, m, d = (int(x) for x in iso.split("-"))
    return f"{d} {MONTHS[m]} {y}"


def load_released():
    cat = json.load(open("data/catalogue.json", encoding="utf-8"))
    cat = cat if isinstance(cat, list) else cat["episodes"]
    out = []
    for e in cat:
        slug = (e.get("slug") or "").strip()
        date = e.get("date") or ""
        if not SLUG_OK.match(slug) or not re.match(r"^\d{4}-\d{2}-\d{2}$", date):
            print(f"::warning::bake_episode_links: EP {e.get('episodeNumber')} has no usable slug/date; skipped")
            continue
        if datetime.date.fromisoformat(date) > TODAY:
            continue
        out.append(e)
    out.sort(key=lambda e: (e["date"], e["episodeNumber"]), reverse=True)  # newest first, same as the page
    return out


def card(e, hidden):
    thumb = e.get("thumbnail") or f"https://i.ytimg.com/vi/{e.get('youtubeId')}/hqdefault.jpg"
    style = ' style="display:none"' if hidden else ""
    guests = ""
    if e.get("guests"):
        names = " &amp; ".join(f"<b>{esc(n)}</b>" for n in e["guests"])
        guests = f'<span class="eg">With {names}</span>'
    return (f'<a class="ecard" href="/{e["slug"]}" data-ep="{e["episodeNumber"]}"{style}>'
            f'<img loading="lazy" alt="" src="{esc(thumb)}">'
            f'<span class="et">{esc(e["title"])}</span>{guests}'
            f'<span class="ef"><span class="ed">{fmt_date(e["date"])}</span>'
            f'<span class="ee">EP {e["episodeNumber"]}</span></span></a>')


def build_block(eps):
    lines = [START]
    for i, e in enumerate(eps):
        lines.append(card(e, hidden=i >= VISIBLE_AT_LOAD))
    lines.append(END)
    return "\n".join(lines)


def atomic_write(path, text):
    fd, tmp = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(path)), prefix=".bake-tmp-")
    with os.fdopen(fd, "w", encoding="utf-8", newline="") as f:
        f.write(text)
    os.replace(tmp, path)


def main():
    page = open(PAGE, encoding="utf-8", newline="").read()
    eps = load_released()
    block = build_block(eps)
    if BLOCK.search(page):
        new = BLOCK.sub(lambda m: block, page, count=1)
    else:
        grid = '<div class="epgrid" id="grid">'
        if grid not in page:
            print(f"::error::bake_episode_links: could not find {grid} in {PAGE}")
            return 1
        new = page.replace(grid, grid + "\n" + block + "\n", 1)
    # sanity: one baked <a href="/slug"> per released episode, no duplicates
    hrefs = re.findall(r'<a class="ecard" href="/([^"]+)" data-ep=', new)
    assert len(hrefs) == len(eps) == len(set(hrefs)), "baked link count mismatch"
    if "--check" in sys.argv[1:]:
        ok = new == page
        print(f"bake_episode_links --check: {len(eps)} released episodes, "
              + ("PASS (baked block up to date)" if ok else "FAIL (episodes.html baked links are out of date)"))
        return 0 if ok else 1
    if new != page:
        atomic_write(PAGE, new)
        print(f"bake_episode_links: wrote {len(eps)} crawlable episode links into {PAGE}")
    else:
        print(f"bake_episode_links: already up to date ({len(eps)} links)")
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception as ex:
        print(f"::warning::bake_episode_links failed, episodes.html left unchanged: {ex}")
        sys.exit(1)
